      rt.sockets.delete(socket);
      for (const s of rt.sockets) if (!s.destroyed) s.write(encodeFrame(0x1, Buffer.from(JSON.stringify({ type: 'left', actor: me }))));
    };
    socket.on('close', cleanup);
    socket.on('error', () => socket.destroy());
  });

  return server;
}
