const COLORS = ['#e11d48', '#2563eb', '#16a34a', '#d97706', '#7c3aed', '#0891b2'];

const S = {
  session: JSON.parse(localStorage.getItem('diagram-s5-session') || 'null'),
  docId: null, meta: null, doc: null, role: null, readOnly: false,
