  const conns = els.filter((e) => e.type === 'connector' && false);
  const extra = S.doc.elements({ type: 'connector' }).filter((c) => ids.has(c.source.elementId) && ids.has(c.target.elementId));
  S.clipboard = [...els.filter((e) => e.type !== 'connector'), ...extra.filter((c) => !ids.has(c.id))].map((e) => structuredClone(e));
