      map.set(e.id, id);
      const { id: _i, z: _z, groupId: _g, source: _s, target: _t, ...rest } = e;
      const layer = S.doc.toJSON().layers.some((l) => l.id === e.layer) ? e.layer : S.activeLayer;
      S.doc.apply({ type: 'add', element: { ...rest, id, x: e.x + offset, y: e.y + offset, layer } });
      newIds.push(id);
